python3 -c "
import json

# Search for exchange rate data in the JSON files
with open('/app/resources/treasury_bulletin_1960_01.json', 'r') as f:
    data = json.load(f)

# Search recursively for any CAD or exchange-related data
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search(item, f'{path}[{i}]')
    elif isinstance(obj, str):
        if 'cad' in obj.lower() or 'canadian' in obj.lower() or 'exchange rate' in obj.lower():
            print(f'{path}: {obj[:200]}')

search(data)
